\put(80,10){\line(1,0){80}} \put(80,30){\line(1,0){80}}
\put(80,10){\line(0,1){20}} \put(100,10){\line(0,1){20}}
\put(120,10){\line(0,1){20}} \put(140,10){\line(0,1){20}}
\put(160,10){\line(0,1){20}}
\put(120,10){\circle*{3}}
\put(85,0){-3} \put(105,0){-1} \put(130,0){1} \put(148,0){3}
